    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50", "from": "2026-03-10", "to": "2026-03-25"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
