    await ui.setToday(pg_uma, "2026-04-22");
    expect(await ui.addPatron(pg_uma, p_cam, "Ada")).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaimTwice(pg_uma, p_ben, {"amount": "4.00", "date": "2026-03-01"}));
