package net.officefloor.hq.app.role;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Gives the user name the role on the sheet, replacing the one it had. */
public class ApplyRole {
    public void apply(@Val RoleInput input, @Val Sheet sheet, RoleRepository repository, Out<Role> roleOut) {
        Role role = repository.findBySheetIdAndUserName(sheet.getId(), input.user())
                .orElseGet(() -> new Role(sheet.getId(), input.user(), input.role()));
        role.setRole(input.role());
        roleOut.set(repository.saveAndFlush(role));
    }
}
package net.officefloor.hq.app.role;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the user name's role, once it is saved. */
public class AuditRoleSet {
    public void audit(@Val Role role, @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        audit.record("ROLE_SET sheet=" + role.getSheetId() + " by=" + AuditUser.decode(user)
                + " user=" + role.getUserName() + " role=" + role.getRole());
    }
}
package net.officefloor.hq.app.role;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidRole {
    public void handle(@Parameter InvalidRoleException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.role;

/** A role form that cannot be saved: a blank user name or a role other than clerk or steward. */
public class InvalidRoleException extends Exception {
    public InvalidRoleException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.role;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRole {
    public void respond(@Val Role role, ObjectResponse<RoleResponse> response) {
        response.send(RoleResponse.from(role));
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRoles {
    public void respond(@Val Sheet sheet, RoleRepository repository, ObjectResponse<List<RoleResponse>> response) {
        response.send(repository.findBySheetIdOrderByUserNameAsc(sheet.getId()).stream().map(RoleResponse::from).toList());
    }
}
package net.officefloor.hq.app.role;

/** A validated role form: a non-blank user name and clerk or steward. */
public record RoleInput(String user, String role) {
