import { useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople, useShowRetired } from '../people/people';
import { claimsPath, claimsQueryKey, useClaims, useSelectedClaims, type Claim } from './claims';

// Opens every selected claim with one button, in list order: the people as listed, newest claim
// first within a person, so the claims are numbered in that order. Each is opened as its own Open
// button would (the server refuses what it refuses there, and that claim is left as it is); the
// counts of opened and refused show once all are done, and are gone while it runs.
function BulkOpen() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const [showRetired] = useShowRetired();
  const { selected, clear } = useSelectedClaims();
  const queryClient = useQueryClient();
  const [result, setResult] = useState<{ opened: number; refused: number } | null>(null);
  const busy = useRef(false);
  if (!user || !sheet) return null;

  const run = async () => {
    if (busy.current) return;
    busy.current = true;
    setResult(null);
    try {
      const listed = (people.data ?? []).filter((p) => showRetired || p.retiredFrom === null);
      const order = listed.flatMap((p) => (claims.data ?? []).filter((c) => c.personId === p.id && selected.has(c.id)));
      let opened = 0;
      let refused = 0;
      for (const c of order) {
        try {
          await putJson<Claim>(`${claimsPath(sheet)}/${c.id}/open`, undefined, user);
          opened++;
        } catch {
          refused++;
        }
      }
      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
      clear();
      setResult({ opened, refused });
    } finally {
      busy.current = false;
    }
  };

  return (
    <div>
      <button type="button" data-testid="bulk-open" onClick={() => void run()}>
        Open selected claims
      </button>
      {result && (
        <>
          {' '}Opened <span data-testid="bulk-opened">{result.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{result.refused}</span>
        </>
      )}
    </div>
  );
}

export const contribution = HomeMain.fill({ order: 21, Component: BulkOpen });
import { useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople, useShowRetired } from '../people/people';
import { claimsPath, claimsQueryKey, useClaims, useSelectedClaims, type Claim } from './claims';

// Settles every selected claim with one button, in list order: the people as listed, newest claim
// first within a person. Each is settled as its own Settle button would, by the signed-in user (the
// server refuses what it refuses there, and that claim is left as it is; one a clerk settles above
// the clerk limit goes PENDING, and counts as settled); the counts of settled and refused show once
// all are done, and are gone while it runs.
function BulkSettle() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const [showRetired] = useShowRetired();
  const { selected, clear } = useSelectedClaims();
  const queryClient = useQueryClient();
  const [result, setResult] = useState<{ settled: number; refused: number } | null>(null);
  const busy = useRef(false);
  if (!user || !sheet) return null;

  const run = async () => {
    if (busy.current) return;
    busy.current = true;
    setResult(null);
    try {
      const listed = (people.data ?? []).filter((p) => showRetired || p.retiredFrom === null);
      const order = listed.flatMap((p) => (claims.data ?? []).filter((c) => c.personId === p.id && selected.has(c.id)));
      let settled = 0;
      let refused = 0;
      for (const c of order) {
        try {
          await putJson<Claim>(`${claimsPath(sheet)}/${c.id}/settle`, undefined, user);
          settled++;
        } catch {
          refused++;
        }
      }
      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
      clear();
      setResult({ settled, refused });
    } finally {
      busy.current = false;
    }
  };

  return (
    <div>
      <button type="button" data-testid="bulk-settle" onClick={() => void run()}>
        Settle selected claims
      </button>
      {result && (
        <>
          {' '}Settled <span data-testid="bulk-settled">{result.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{result.refused}</span>
        </>
      )}
    </div>
  );
}

export const contribution = HomeMain.fill({ order: 22, Component: BulkSettle });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
